/**
 * emit to subscription queries of type FindAdSlot,
 * but only if the id matches
 *
 * @param		entity	AdSlot
 */
	protected void emitFindAdSlot( AdSlot entity ) {
		LOGGER.info("handling emitFindAdSlot" );
		
	    queryUpdateEmitter.emit(FindAdSlotQuery.class,
	                            query -> query.getFilter().getAdSlotId().equals(entity.getAdSlotId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAdSlot
	 * 
	 * @param		entity	AdSlot
	 */
	protected void emitFindAllAdSlot( AdSlot entity ) {
		LOGGER.info("handling emitFindAllAdSlot" );
		
	    queryUpdateEmitter.emit(FindAllAdSlotQuery.class,
	                            query -> true,
	                            entity);
	}

